type State =
  | { kind: 'loading' }
  | { kind: 'success'; data: string[] }
  | { kind: 'error'; message: string };

function render(s: State): string {
  switch (s.kind) {
    case 'loading': return '...';
    case 'success': return s.data.join(', ');
    case 'error':   return s.message;
    default: { const _exhaustive: never = s; return _exhaustive; }
  }
}

